// What each API call does, for mintlify/openapi.json (scripts/gen-openapi.js). One entry per route the server
// registers, keyed "METHOD /path" exactly as scripts/gen-api-routes.js reads it from the code: a route without an entry
// here (or an entry without a route) fails `node scripts/gen-openapi.js --check` and `npm test`.
//
// Fields: tag, summary (the page title), description (plain English, Markdown), body (a schema or a schema name),
// bodyExample, bodyOptional (an empty body is fine), query ([{name, description, schema?, required?}]), params
// ({name: description} for the :params in the path), res (the 200 answer's schema or schema name), example,
// errors ({status: example message}; 403 for locked calls is added from the route's area), content (a non-JSON answer).
import { ref, obj, arr, str, num, int, bool, en, loose, nullable } from "./schemas.js";

const OK = "Ok", R = name => ref(name);
const minutes = (d, lo, hi) => obj({ minutes: int(d, { minimum: lo, maximum: hi }), key: str("The wake-up link key, instead of the header or `?key=`.") });
const homeOps = "Answers the home status (also `status.home`).";
const homeEx = { wake: null, nextWake: "2026-11-05T06:30:00.000Z", sleep: null, plan: null };

export const tags = [
  ["State", "Everything the web app reads to draw itself, and a health check for monitoring."],
  ["Status", "What is happening right now: the music source, tempo, song part, effect, devices and their latency."],
  ["Lights & show", "Power, brightness, effects, zones and the live pads."],
  ["Your own effects", "Effects you build from parts on the Effects page. Each gets an id (`u-…`) to use like any built-in effect."],
  ["Scenes & schedules", "Saved looks, and times at which they (or on, off, a brightness) happen by themselves."],
  ["Home & sleep", "Sunrise alarm, sleep timer and the ambient plan for the day. The wake and sleep calls also take the wake-up link key, for phone automations."],
  ["Devices & room", "Light controllers (WLED, Hue, Nanoleaf, Govee, OpenRGB, LIFX, WiZ, Kasa, Yeelight, Twinkly, DMX) and where their LEDs are in the room."],
  ["DMX", "Fixtures on an Art-Net or sACN universe: pars, moving heads, lasers, fog."],
  ["Music", "Songs played in a browser, their clock, song memory and each song's editable show."],
  ["Hearing", "How Tempolight hears the music: the guided panel on the Music page."],
  ["Now playing", "The track music apps on this computer play, and the Spotify sign-in."],
  ["Music library", "Your own music folders, analysed ahead so every song is followed from its first play. Node server only, admin only."],
  ["Spotify", "Lights that follow the Spotify track with its beat map."],
  ["Claude show designer", "Optional: with your own Anthropic API key, Claude designs each song's show (energy arc, drop sections, palettes, moments). Node server only, admin only to change."],
  ["Requests", "Guest song requests from `/request`. Open to everyone, even when locked."],
  ["Settings", "Every setting, in one call."],
  ["Backup & updates", "Backup, restore, reset to defaults, updates and quitting."],
  ["Wi-Fi", "The Raspberry Pi image's Wi-Fi setup."],
  ["Lock", "The PIN lock and unlock tokens."],
  ["Apple Home", "The built-in HomeKit bridge."],
  ["Integrations", "OBS, Twitch, Discord and the Stream Deck plugin. Node server only."],
  ["Games", "Counter-Strike 2 and Dota 2 game-state integration."],
].map(([name, description]) => ({ name, description }));

export const operations = {
  // ============================================================ State
  "GET /api/state": { tag: "State", summary: "Get the whole state", res: "State",
    description: "Everything the web app draws: settings, show, devices, room, scenes, schedules (each with its next run), effects, styles, palettes, room presets and sound sources. Secrets are left out: `settings.mqtt.password` is blank and `hasPassword` says one is saved." },
  "GET /api/health": { tag: "State", summary: "Health check", res: "Health", description: "A small answer for monitoring: the version, seconds running, frames a second and LEDs." },
  "GET /api/effects": { tag: "State", summary: "List effects", res: arr(R("Effect")), example: [{ id: "shock", name: "Shock", tag: "drop" }, { id: "u-k3j9q2", name: "Pink chase", tag: "drop", custom: true }],
    description: "Every effect, built-in and your own." },
  "GET /api/layout": { tag: "State", summary: "Get the LED layout", res: "Layout", description: "Where every LED is, in the order the preview frames on the WebSocket use: positions, the shape each LED belongs to and each device's range." },
  "GET /api/log": { tag: "State", summary: "Get the activity log", res: arr(R("LogEntry")), description: "The last 100 activity messages." },
  "GET /api/network": { tag: "State", summary: "Get this computer's addresses", res: obj({ addresses: arr(str()) }), example: { addresses: ["192.168.1.20"] },
    description: "This computer's LAN addresses, for the phone QR code." },

  // ============================================================ Status
  "GET /api/status": { tag: "Status", summary: "Get the live status", res: "Status",
    description: "What is happening now: the music source, tempo, song part, beat, the effect, loudness, key and mood, the song, the pads, home, MQTT, and per device what is sent and the sound-to-light latency. The WebSocket sends the same object 4 times a second." },

  // ============================================================ Lights & show
  "POST /api/power": { tag: "Lights & show", summary: "Turn the lights on or off", body: obj({ on: bool("Left out: toggle.") }), bodyOptional: true, bodyExample: { on: true }, res: "Show",
    description: "Turns the lights on or off; with no body, toggles them. Answers the show." },
  "POST /api/brightness": { tag: "Lights & show", summary: "Set brightness", body: obj({ value: num("0 to 1.", { minimum: 0, maximum: 1 }) }, { required: ["value"] }), bodyExample: { value: 0.6 },
    res: obj({ brightness: num() }), example: { brightness: 0.6 }, description: "Sets the master brightness, 0 to 1 (out of range is clamped)." },
  "PATCH /api/show": { tag: "Lights & show", summary: "Change the show", body: "ShowPatch", bodyExample: { effect: "laser" }, res: "Show", errors: { 400: 'Unknown effect "x"' },
    description: "Changes any of the mode, effect, style, palette, how often effects change, speed and the accent layer. Setting `effect` alone switches to manual mode. Answers the show." },
  "PATCH /api/effects/{id}": { tag: "Lights & show", summary: "Like, ban or tune an effect", params: { id: "An effect id." },
    body: obj({ pref: { type: "integer", enum: [1, 0, -1], description: "1 like, -1 ban, 0 neither." }, params: nullable(R("EffectParams")) }), bodyExample: { pref: 1 },
    res: obj({ id: str(), pref: int(), params: nullable(R("EffectParams")) }), example: { id: "laser", pref: 1, params: null }, errors: { 404: 'Unknown effect "x"' },
    description: "`pref: 1` likes it and `-1` bans it for automatic mode (`0`: neither). `params` sets its speed, intensity, hue, saturation and mirror; `params: null` resets them." },
  "PUT /api/zones": { tag: "Lights & show", summary: "Set the zones", body: obj({ zones: arr(R("Zone"), undefined, { maxItems: 32 }) }, { required: ["zones"] }),
    bodyExample: { zones: [{ id: "z1", name: "Desk", mode: "effect", effect: "aurora", brightness: 0.7 }] }, res: arr(R("Zone")), errors: { 400: 'Zone "Desk": pick an effect' },
    description: "Replaces the zones (at most 32). A zone follows the show, shows its own effect, the ambient look, or is off. Shapes join a zone with their `zone` field." },
  "POST /api/action": { tag: "Lights & show", summary: "Trigger a live pad", body: "Action", bodyExample: { type: "flash", color: "#ff0066" }, res: "Pads", errors: { 400: 'Unknown action "x"' },
    description: "A live pad: flash, strobe, blackout, freeze, hold a colour, boost, next effect, a drop now, a build-up, cancel, tap tempo, identify a device or shape, or the DMX fog pad. Also over the WebSocket, OSC and MQTT. Answers the pads' state." },

  // ============================================================ Your own effects
  "GET /api/custom-effects": { tag: "Your own effects", summary: "List your effects", res: arr(R("CustomEffect")), description: "The effects you made." },
  "POST /api/custom-effects": { tag: "Your own effects", summary: "Make an effect", body: "CustomEffectInput", res: "CustomEffect", errors: { 400: "Pattern is one of: wave, chase, pulse, sparkle, fill, breathe, gradient" },
    description: "Makes an effect from a pattern, an axis, what drives it and its colours. Answers it with its id (`u-…`). At most 100." },
  "PUT /api/custom-effects/{id}": { tag: "Your own effects", summary: "Change an effect", params: { id: "Your effect's id (`u-…`)." }, body: "CustomEffectInput", res: "CustomEffect", errors: { 400: "Colours are two like #ff0066", 404: "No such effect" },
    description: "Replaces your effect with this one (the same body as making it)." },
  "DELETE /api/custom-effects/{id}": { tag: "Your own effects", summary: "Delete an effect", params: { id: "Your effect's id (`u-…`)." }, res: OK, errors: { 404: "No such effect" },
    description: "Deletes it and every reference to it: the shown effect, the layer, ambient, zones, scenes, likes and song shows." },

  // ============================================================ Scenes & schedules
  "GET /api/scenes": { tag: "Scenes & schedules", summary: "List scenes", res: arr(R("Scene")), description: "Your scenes. New installs start with `party`, `chill`, `movie`, `focus` and `relax`." },
  "POST /api/scenes": { tag: "Scenes & schedules", summary: "Save a scene", body: obj({ name: str(undefined, { maxLength: 60 }), show: loose("The show fields to set; left out: the current show."), brightness: num() }),
    bodyExample: { name: "Movie night" }, res: "Scene", description: "`{name}` saves the current look as a scene; or give its `show` and `brightness`." },
  "PUT /api/scenes/{id}": { tag: "Scenes & schedules", summary: "Change a scene", params: { id: "A scene id." }, body: obj({ name: str(), show: loose("The show fields to set."), brightness: num() }),
    bodyExample: { brightness: 0.5 }, res: "Scene", errors: { 404: "No such scene" }, description: "Changes its name, show or brightness." },
  "DELETE /api/scenes/{id}": { tag: "Scenes & schedules", summary: "Delete a scene", params: { id: "A scene id." }, res: OK, description: "Deletes it (no error when it doesn't exist)." },
  "POST /api/scenes/{id}/apply": { tag: "Scenes & schedules", summary: "Apply a scene", params: { id: "A scene id, for example `party`." }, res: "Show", errors: { 404: "No such scene" },
    description: "Applies the scene and turns the lights on. Answers the show." },
  "GET /api/schedules": { tag: "Scenes & schedules", summary: "List schedules", res: arr(R("Schedule")), description: "Your schedules, each with `next`: the next time it runs." },
  "POST /api/schedules": { tag: "Scenes & schedules", summary: "Add a schedule", body: "ScheduleInput", res: "Schedule", errors: { 400: "Time must look like 18:30, sunset or sunrise-15" },
    description: "At a time (`19:00`, or `sunset+30` once a location is set) on some weekdays, apply a scene, turn the lights on or off, or set a brightness." },
  "PUT /api/schedules/{id}": { tag: "Scenes & schedules", summary: "Change a schedule", params: { id: "A schedule id (`t…`)." }, body: "ScheduleInput", bodyExample: { enabled: false }, res: "Schedule",
    errors: { 400: "Pick a scene for this schedule", 404: "No such schedule" }, description: "Changes the fields given; the others are kept." },
  "DELETE /api/schedules/{id}": { tag: "Scenes & schedules", summary: "Delete a schedule", params: { id: "A schedule id (`t…`)." }, res: OK, description: "Deletes it (no error when it doesn't exist)." },
  "POST /api/schedules/{id}/run": { tag: "Scenes & schedules", summary: "Run a schedule now", params: { id: "A schedule id (`t…`)." }, res: OK, errors: { 404: "No such schedule" }, description: "Does what the schedule does, now." },

  // ============================================================ Home & sleep
  "GET /api/home": { tag: "Home & sleep", summary: "Get home settings", res: "Home", description: "The wake-up, sleep timer and ambient plan settings and the home status. `wake.key` is only there when unlocked." },
  "PUT /api/home": { tag: "Home & sleep", summary: "Change home settings", body: "HomeUpdate", res: "Home", errors: { 400: "The sunrise takes 10 to 40 minutes" },
    description: "Any of the wake-up alarm (days, how long the sunrise takes, where, its end colour and brightness, hold and snooze), the default sleep timer, and the ambient plan's rows." },
  "POST /api/wake": { tag: "Home & sleep", summary: "Start a sunrise", body: obj({ inMinutes: num(), at: { anyOf: [str("`07:00` or an ISO date."), num("Milliseconds since 1970.")] }, duration: int("Minutes, 1 to 120.", { minimum: 1, maximum: 120 }), key: str("The link key.") }),
    bodyOptional: true, bodyExample: { at: "07:00", duration: 20 }, res: "HomeStatus", example: homeEx,
    errors: { 400: "at is a time like 07:00, an ISO date or milliseconds, within 36 hours", 409: "Wake-up is turned off (Home & sleep page)" },
    description: `Full light at that time (within 36 hours); with no time, the sunrise starts now. 409 when wake-up is off. ${homeOps}` },
  "DELETE /api/wake": { tag: "Home & sleep", summary: "Cancel the next sunrise", res: "HomeStatus", example: homeEx, description: `Cancels the next sunrise, or skips the next weekly alarm. ${homeOps}` },
  "POST /api/wake/snooze": { tag: "Home & sleep", summary: "Snooze the sunrise", body: minutes("Snooze for this long (default: the wake-up's snooze setting)."), bodyOptional: true, bodyExample: { minutes: 9 }, res: "HomeStatus", example: homeEx,
    description: `Snoozes a running sunrise. ${homeOps}` },
  "POST /api/wake/stop": { tag: "Home & sleep", summary: "Stop the sunrise", res: "HomeStatus", example: homeEx, description: `Stops the running sunrise. ${homeOps}` },
  "POST /api/wake/key": { tag: "Home & sleep", summary: "Make a new link key", res: obj({ key: str() }), example: { key: "8c1f0e7d2b3a4c5d" },
    description: "Makes a new wake-up link key; the old one stops working. The key opens the wake and sleep calls only, for phone automations." },
  "POST /api/sleep": { tag: "Home & sleep", summary: "Start the sleep timer", body: minutes("1 to 180 (default: the sleep setting).", 1, 180), bodyOptional: true, bodyExample: { minutes: 30 }, res: "HomeStatus",
    errors: { 400: "minutes is 1 to 180" }, description: `Fades the lights out and turns them off. A brightness or power change cancels it. ${homeOps}` },
  "DELETE /api/sleep": { tag: "Home & sleep", summary: "Cancel the sleep timer", res: "HomeStatus", example: homeEx, description: `Cancels the sleep timer. ${homeOps}` },

  // ============================================================ Devices & room
  "GET /api/devices": { tag: "Devices & room", summary: "List devices", res: arr(R("Device")), description: "Your devices, each with `health`: the last check. Hue user names and client keys and Nanoleaf tokens never leave the server." },
  "POST /api/devices": { tag: "Devices & room", summary: "Add a device", body: "DeviceInput", res: "Device", errors: { 400: "Couldn't reach a WLED controller at 192.168.1.42 (timeout). Check the address, or add it anyway." },
    description: "Adds a controller by kind: WLED by address (its LED count is read from it), a virtual room, Govee, OpenRGB, Hue (press the link button first), Nanoleaf (hold the power button first), LIFX, WiZ, Kasa, Yeelight, Twinkly, or a DMX universe. It is placed in the room by itself. Answers the device; adding one that is already there answers that one." },
  "PATCH /api/devices/{id}": { tag: "Devices & room", summary: "Change a device", params: { id: "A device id (`d…`)." }, body: "DevicePatch", res: "Device", errors: { 400: "Protocol is ddp, e131 or artnet", 404: "No such device" },
    description: "Changes its name, address, LED count, protocol, power limit and per-kind options. Hue: `{hueFast: true}` turns on fast mode (Entertainment streaming); a bridge paired before needs its link button pressed first, and the answer says so." },
  "DELETE /api/devices/{id}": { tag: "Devices & room", summary: "Remove a device", params: { id: "A device id (`d…`)." }, res: OK, errors: { 404: "No such device" }, description: "Removes it and its shapes." },
  "POST /api/devices/{id}/check": { tag: "Devices & room", summary: "Check a device", params: { id: "A device id (`d…`)." }, res: "DeviceHealth", errors: { 404: "No such device" },
    example: { online: true, version: "0.15.0", ledsReported: 120, lastSeen: 1762200000000, error: null, rssi: -58, signal: 84, rttMs: 6 }, description: "Checks it now and answers its health." },
  "POST /api/devices/{id}/identify": { tag: "Devices & room", summary: "Identify a device", params: { id: "A device id (`d…`)." }, res: OK, description: "Lights that controller's shapes for a few seconds." },
  "POST /api/devices/{id}/segments": { tag: "Devices & room", summary: "Write WLED segments", params: { id: "A WLED device id (`d…`)." },
    res: obj({ segments: arr(obj({ start: int(), end: int(), name: str(), rev: bool() })) }), example: { segments: [{ start: 0, end: 120, name: "Desk strip", rev: false }] },
    description: "Writes the room's LED ranges for this controller into WLED as segments." },
  "POST /api/discover": { tag: "Devices & room", summary: "Find devices", body: obj({ scan: bool("Also scan the network (default true)."), hosts: arr(str(), "Extra addresses to try.") }), bodyOptional: true, bodyExample: { scan: true },
    res: arr(R("DiscoveredDevice")), description: "Looks for WLED controllers (mDNS and a network scan), Govee lights, OpenRGB devices on this computer and LIFX, WiZ, Kasa, Yeelight and Twinkly lights. Each says whether it is `added` already. Takes a few seconds." },
  "GET /api/room": { tag: "Devices & room", summary: "Get the room", res: "Room", description: "The room's name, shapes and zones." },
  "PUT /api/room": { tag: "Devices & room", summary: "Set the room", body: obj({ name: str(), shapes: arr(R("Shape")) }, { required: ["shapes"] }), res: "Room", errors: { 400: "Shape \"Desk strip\" points at a device that doesn't exist" },
    bodyExample: { name: "Living room", shapes: [{ type: "line", name: "Desk strip", count: 120, dev: "d4k2x9", pts: [[1.5, 6], [14.5, 6]] }] }, description: "Replaces the shapes (the zones are kept)." },
  "POST /api/room/preset": { tag: "Devices & room", summary: "Use a room preset", body: obj({ id: str("A preset id from `presets` in the state.") }, { required: ["id"] }), bodyExample: { id: "fourwalls" }, res: "Room",
    errors: { 400: 'Unknown preset "x"' }, description: "Lays out the room from a ready-made layout, built for your controllers." },
  "POST /api/room/identify": { tag: "Devices & room", summary: "Identify a shape", body: obj({ shape: int("The shape's index in the room.") }, { required: ["shape"] }), bodyExample: { shape: 0 }, res: OK,
    description: "Lights one shape for a few seconds." },
  "POST /api/map": { tag: "Devices & room", summary: "Camera mapping", body: obj({ device: str(), led: int("The LED to light; -1: all dark."), level: num(), end: bool("Back to the show.") }), bodyExample: { device: "d4k2x9", led: 17 }, res: OK,
    errors: { 404: "No such device" }, description: "Lights only one LED of a device, for mapping the room with a camera; `{end: true}` goes back to the show. Stops by itself after 5 s without news. Also over the WebSocket." },

  // ============================================================ DMX
  "GET /api/dmx": { tag: "DMX", summary: "Get DMX output", res: obj({ settings: loose("The DMX settings."), status: loose("`{lasers: {on, why}, fog: {on, why, duty, maxDuty, cooldownLeft}}`."), devices: arr(loose("A DMX device with `values` (512 channels), its fixtures with `kind` and `live` channel values, and `warnings`.")) }),
    description: "Every DMX universe with every channel's value now, its fixtures, and whether lasers and fog may run." },
  "GET /api/dmx/profiles": { tag: "DMX", summary: "List fixture profiles", res: obj({ profiles: arr(obj({ id: str(), name: str(), kind: str(), channels: arr(str()) })), channelTypes: arr(str()), patterns: arr(str()) }),
    example: { profiles: [{ id: "rgb", name: "RGB par", kind: "par", channels: ["red", "green", "blue"] }], channelTypes: ["red", "green", "blue", "dimmer"], patterns: ["circle", "figure8", "sweep", "point", "still"] },
    description: "The fixture profiles, the channel types a custom fixture can use, and the moving-head patterns." },
  "POST /api/devices/{id}/fixtures": { tag: "DMX", summary: "Add a fixture", params: { id: "A DMX device id (`d…`)." }, body: "FixtureInput", res: "FixtureResult",
    errors: { 400: "The DMX address is 1 to 512", 404: "No such device" },
    description: "Adds a fixture to a DMX universe. Each fixture is a point of the device's shape in the room; `x, y` place it. Answers it with warnings about overlapping channels. At most 128 per universe." },
  "PATCH /api/devices/{id}/fixtures/{fid}": { tag: "DMX", summary: "Change a fixture", params: { id: "A DMX device id (`d…`).", fid: "A fixture id (`f…`)." }, body: "FixtureInput", bodyExample: { address: 17 }, res: "FixtureResult",
    errors: { 400: "The DMX address is 1 to 512", 404: "No such fixture" }, description: "Changes the fields given." },
  "DELETE /api/devices/{id}/fixtures/{fid}": { tag: "DMX", summary: "Remove a fixture", params: { id: "A DMX device id (`d…`).", fid: "A fixture id (`f…`)." }, res: OK, errors: { 404: "No such fixture" }, description: "Removes it and its point in the room." },

  // ============================================================ Music
  "POST /api/song": { tag: "Music", summary: "Start a song", body: "SongInput", res: OK, errors: { 400: "Send the song's analysis" },
    description: "A song about to play in a browser, with its analysis (from `preAnalyseCore()` in `/engine/analysis.js`). With song memory on, songs over 20 s are remembered. Then send its clock." },
  "POST /api/song/clock": { tag: "Music", summary: "Send the song's clock", body: "SongClock", res: OK,
    description: "Where the song is now. Send it on play, pause and seek, and every second or so (the WebSocket's `clock` message does the same)." },
  "DELETE /api/song": { tag: "Music", summary: "Stop the song", res: OK, description: "The song stopped." },
  "GET /api/song/map": { tag: "Music", summary: "Get the playing song's map", res: "SongMap",
    description: "The map of what plays now: its loudness, sections (repeats share a label), drops and bars, and where it is. Known ahead for a song played here, a remembered song a music app plays, or one song memory recognised. A song heard live that Tempolight doesn't know gets a map made as it is heard (`growing: true`). `source: null` when nothing plays." },
  "GET /api/songs/{id}/map": { tag: "Music", summary: "Get a song's map", params: { id: "A song id (`m…`)." }, res: "SongMap", errors: { 404: "That song isn't remembered" },
    description: "The map of a remembered song: its loudness, sections, drops and bars (`pos` is `null`)." },
  "POST /api/song/look/next": { tag: "Music", summary: "Not this one: the next look", body: "LookRequest", res: "Look", errors: { 404: "Nothing is playing with a look (automatic mode, variety one look or song parts)" },
    description: "Picks the next best look for the song playing (or the remembered song `id`). The look turned down goes into the song's `rejected` list and won't come back for it, and counts a little against that effect for other songs. While listening live to a song Tempolight doesn't know, it picks again from what it hears." },
  "POST /api/song/look/keep": { tag: "Music", summary: "Keep the look", body: "LookRequest", res: "Look", errors: { 404: "That song isn't remembered" },
    description: "The song keeps its look: it isn't picked again when the picker improves, and the effect counts a little more for other songs. `keep: false` lets it change again." },
  "GET /api/audio/sources": { tag: "Music", summary: "List sound inputs", res: arr(R("SoundSource")), description: "Sound inputs the server can capture from (turn capture on in Settings)." },
  "GET /api/songs": { tag: "Music", summary: "List remembered songs", res: arr(R("SongSummary")), description: "Song memory: songs Tempolight has analysed, learned from Spotify or got from the shared beat-map service." },
  "DELETE /api/songs/{id}": { tag: "Music", summary: "Forget a song", params: { id: "A song id (`m…`)." }, res: OK, errors: { 404: "That song isn't remembered" }, description: "Removes it from song memory." },
  "GET /api/songs/{id}/show": { tag: "Music", summary: "Get a song's show", params: { id: "A song id (`m…`)." }, errors: { 404: "That song isn't remembered" },
    res: { allOf: [R("SongShow"), obj({ bpm: num(), P: num(), off: num(), barOff: num(), style: str(), drops: {}, bars: {}, env: str("Loudness, 10 values a second, as base64 bytes."), palettes: { type: "object", additionalProperties: arr(str()) } })] },
    example: { id: "m9x2q1", name: "One More Time", dur: 320.4, edited: false, show: [{ t0: 0, t1: 32, part: "calm", effect: "aurora" }], colors: [], cues: [], bright: [], bpm: 122.7, style: "party", palettes: { sunset: ["#ff5e3a", "#ffb347"] } },
    description: "The song's timeline of effects, colours, cues and brightness (made automatically the first time), plus what the show editor draws: the beat grid, bars, drops, loudness and the palettes' colours." },
  "PUT /api/songs/{id}/show": { tag: "Music", summary: "Save a song's show", params: { id: "A song id (`m…`)." }, body: "SongShowInput", res: { allOf: [R("Ok"), R("SongShow")] },
    example: { ok: true, id: "m9x2q1", name: "One More Time", dur: 320.4, edited: true, show: [{ t0: 0, t1: 32, part: "calm", effect: "aurora" }], colors: [], cues: [], bright: [] },
    errors: { 400: "show is a list of {t0, t1, effect}", 404: "That song isn't remembered" }, description: "Your own timeline for the song; fields left out are kept." },
  "DELETE /api/songs/{id}/show": { tag: "Music", summary: "Reset a song's show", params: { id: "A song id (`m…`)." }, res: { allOf: [R("Ok"), R("SongShow")] }, errors: { 404: "That song isn't remembered" },
    example: { ok: true, id: "m9x2q1", name: "One More Time", dur: 320.4, edited: false, show: [{ t0: 0, t1: 32, part: "calm", effect: "aurora" }], colors: [], cues: [], bright: [] },
    description: "Throws away your edits (colours, cues and brightness too) and makes a new show." },
  "PUT /api/songs/{id}/show/draft": { tag: "Music", summary: "Preview a draft show", params: { id: "A song id (`m…`)." }, body: "SongShowInput", res: OK, errors: { 404: "That song isn't remembered" },
    description: "Plays an unsaved version on the lights for two minutes without saving it: the show editor's live preview." },
  "DELETE /api/songs/{id}/show/draft": { tag: "Music", summary: "Stop the draft", params: { id: "A song id (`m…`)." }, res: OK, description: "Stops playing the draft." },

  // ============================================================ Hearing
  "GET /api/hearing": { tag: "Hearing", summary: "Get the hearing panel", res: "Hearing", description: "The platform, the recommended way to hear music, the checklist, server capture and the sound output." },
  "POST /api/hearing/check": { tag: "Hearing", summary: "Check again", res: "Hearing", description: "The same, detecting everything again now." },
  "POST /api/hearing/use": { tag: "Hearing", summary: "Choose how to hear music", body: obj({ choice: en(["computer", "mic", "pi", ""]) }, { required: ["choice"] }), bodyExample: { choice: "computer" }, res: "Hearing",
    errors: { 400: "Choose computer, mic or pi" }, description: "Turns that way on: this computer's sound, a browser's microphone, or a sound input on a Pi (and server capture on or off)." },

  // ============================================================ Music library
  "GET /api/library": { tag: "Music library", summary: "Get the music library", res: "Library", query: [{ name: "songs", description: "`0` leaves the song list out (for the progress)." }],
    description: "The folders, what was found and analysed, the progress (`Analysing 34 of 210 · 1.2 s each`), whether ffmpeg is installed, and the songs with their tempo, key and look." },
  "PATCH /api/library": { tag: "Music library", summary: "Change the folders", body: obj({ folders: arr(str("A full path on the computer Tempolight runs on (`~/Music` works).")), watch: bool() }), bodyExample: { folders: ["/music"], watch: true }, res: "Library",
    errors: { 400: "There is no folder /musik on the computer Tempolight runs on" },
    description: "Sets the music folders (the whole list) and whether new songs are noticed by themselves, then looks through them. Each folder must be a full path to an existing folder, not a whole disk; files are never read outside these folders (links that lead out are not followed). Taking a folder out takes its songs out of the library." },
  "POST /api/library/scan": { tag: "Music library", summary: "Look for new songs", res: "Library", errors: { 400: "Add a music folder first" },
    description: "Looks through the folders now. New and changed files are analysed; files already analysed (same path, size and time) are skipped, and copies are kept once." },
  "POST /api/library/pause": { tag: "Music library", summary: "Pause analysing", res: "Library", description: "Stops the analysis at once (the songs being analysed start again on resume). Stays paused after a restart." },
  "POST /api/library/resume": { tag: "Music library", summary: "Resume analysing", res: "Library", description: "Goes on analysing." },
  "DELETE /api/library/songs/{id}": { tag: "Music library", summary: "Remove a song", params: { id: "The song's id (`l…`)." }, res: R(OK), errors: { 404: "That song isn't in the library" },
    description: "Takes the song out of the library. The file stays; it isn't added again unless it changes." },

  // ============================================================ Now playing
  "GET /api/nowplaying": { tag: "Now playing", summary: "Get now playing", res: "NowPlaying",
    description: "Whether reading what music apps play works here, how, the track, and the Spotify account. When the track is a remembered song, the lights follow its beat map." },
  "PATCH /api/nowplaying": { tag: "Now playing", summary: "Change now playing", body: obj({ enabled: bool(), spotifyClientId: str("32 hex digits, from developer.spotify.com/dashboard.") }), bodyExample: { enabled: true }, res: "NowPlaying",
    errors: { 400: "A Spotify Client ID is 32 letters and digits (0-9, a-f), from developer.spotify.com/dashboard" }, description: "Turns it on or off, and sets the Spotify app's Client ID." },
  "POST /api/nowplaying/spotify/login": { tag: "Now playing", summary: "Start the Spotify sign-in", res: obj({ url: str(), redirectUri: str() }),
    example: { url: "https://accounts.spotify.com/authorize?client_id=…", redirectUri: "http://127.0.0.1:8080/api/nowplaying/spotify/callback" },
    description: "Answers the Spotify sign-in address (PKCE, no client secret). Open it; Spotify comes back to `redirectUri`, which must be added to your Spotify app." },
  "GET /api/nowplaying/spotify/callback": { tag: "Now playing", summary: "Spotify sign-in callback",
    query: [{ name: "code", description: "From Spotify." }, { name: "state", description: "From Spotify." }, { name: "error", description: "From Spotify, when signing in failed." }],
    content: { "text/html": { schema: str("A small page saying whether it worked.") } },
    extraResponses: { 400: { description: "Signing in failed: the same page, saying why.", content: { "text/html": { schema: str() } } } },
    description: "Where Spotify sends the browser after signing in. Answers a small HTML page, not JSON (400 when it failed)." },
  "POST /api/nowplaying/spotify/code": { tag: "Now playing", summary: "Finish the Spotify sign-in", body: obj({ url: str("The address Spotify sent the browser to."), code: str(), state: str() }),
    bodyExample: { url: "http://127.0.0.1:8080/api/nowplaying/spotify/callback?code=AQB…&state=x1y2" }, res: "NowPlaying", errors: { 400: "Paste the whole address from the browser's address bar" },
    description: "For signing in from another device: paste the address Spotify sent the browser to (or its `code` and `state`)." },
  "DELETE /api/nowplaying/spotify": { tag: "Now playing", summary: "Disconnect Spotify", res: "NowPlaying", description: "Forgets the Spotify sign-in." },

  // ============================================================ Spotify
  "GET /api/spotify": { tag: "Spotify", summary: "Get Spotify sync", res: "Spotify", description: "The sync settings, the mode (`exact`, `shared`, `analysis`, `learning`, `live`, `paused`, `idle`, `off`), the track and its beat map, learning progress and the cover colours." },
  "PATCH /api/spotify": { tag: "Spotify", summary: "Change Spotify sync", res: "Spotify", errors: { 400: "The beat-map service address starts with https:// (your Worker's address)" },
    body: obj({ sync: bool(), learn: bool(), analysis: bool(), coverColours: bool(), pauseFade: bool(), muteDim: bool(), cloud: obj({ url: str(), use: bool(), share: bool() }) }), bodyExample: { sync: true, coverColours: true },
    description: "Any of: follow Spotify, learn beat maps by listening, use Spotify's own analysis, cover colours, fade on pause, dim when muted, and the shared beat-map service." },
  "POST /api/spotify/colors": { tag: "Spotify", summary: "Send cover colours", body: obj({ art: str("The cover's https address."), colors: arr(str(), "2 to 4 colours.", { minItems: 2, maxItems: 4 }) }, { required: ["art", "colors"] }),
    bodyExample: { art: "https://i.scdn.co/image/ab67616d0000b273", colors: ["#1db954", "#191414", "#ffffff"] }, res: OK, errors: { 400: "{art, colors: ['#rrggbb', '#rrggbb', ...]}" },
    description: "The album cover's colours, which the browser works out, for the palette." },

  // ============================================================ Claude show designer
  "GET /api/designer": { tag: "Claude show designer", summary: "Get the designer", res: "Designer", description: "On or off, whether a key is saved (never the key), the model, the daily limit, today's requests and tokens, and the estimated tokens and cost of a request for the song playing." },
  "PATCH /api/designer": { tag: "Claude show designer", summary: "Change the designer", res: "Designer",
    body: obj({ enabled: bool(), apiKey: str("Your Anthropic API key (`sk-ant-…`). Kept on this computer, never sent back."), clearKey: bool("Forget the saved key."), model: str("A model id, like `claude-sonnet-5-5`."), dailyCap: int("Requests a day at most, 0 to 500.", { minimum: 0, maximum: 500 }) }),
    bodyExample: { enabled: true, apiKey: "sk-ant-api03-…", model: "claude-sonnet-5-5", dailyCap: 30 }, errors: { 400: "That doesn't look like an Anthropic API key (it starts with sk-ant-)" },
    description: "Any of: on or off, the API key, the model and the daily limit." },
  "POST /api/designer/test": { tag: "Claude show designer", summary: "Test the key", res: obj({ ok: bool(), model: str(), ms: num(), error: str() }), example: { ok: true, model: "claude-sonnet-5-5", ms: 640 },
    errors: { 400: "Paste your Anthropic API key first" }, description: "Sends a tiny request (16 tokens at most) with the saved key and model. It doesn't count against the daily limit. `ok: false` with `error` when Anthropic turns it down." },
  "GET /api/songs/{id}/design": { tag: "Claude show designer", summary: "Get a song's design", res: "SongDesign", params: { id: "A remembered song's id (`m…`)." }, errors: { 404: "That song isn't remembered" },
    description: "The song's design per section (arc, effect, palette, Claude's reason), its moments, whether it plays now, and the estimated cost of asking again. `design` is `null` when it has none." },
  "POST /api/songs/{id}/design": { tag: "Claude show designer", summary: "Redesign with Claude", res: "SongDesign", params: { id: "A remembered song's id (`m…`)." },
    errors: { 400: "Turn on the Claude show designer in Settings first", 404: "That song isn't remembered", 409: "Claude is designing this song already", 429: "The daily limit of 30 designs is reached. Raise it in Settings → Claude, or try tomorrow.", 502: "Claude couldn't design this song: unknown effect \"x\". It keeps its automatic look." },
    description: "Asks Claude for a new design now (one request, counted against the daily limit). Answers within about 10 seconds; a wrong or late answer is thrown away (502) and the song keeps what it had." },
  "DELETE /api/songs/{id}/design": { tag: "Claude show designer", summary: "Use the automatic look", res: "SongDesign", params: { id: "A remembered song's id (`m…`)." }, errors: { 404: "That song isn't remembered" },
    description: "Drops the song's design: it plays its automatic look, and isn't asked about again by itself." },

  // ============================================================ Requests
  "GET /api/requests": { tag: "Requests", summary: "List requests", res: obj({ enabled: bool(), requests: arr(R("SongRequest")) }),
    example: { enabled: true, requests: [{ id: "r2k8d1", title: "Daft Punk – One More Time", by: "Sam", votes: 3, at: 1762200000000 }] }, description: "Open requests, most votes first." },
  "POST /api/requests": { tag: "Requests", summary: "Request a song", body: obj({ title: str(undefined, { minLength: 2, maxLength: 120 }), by: str(undefined, { maxLength: 40 }) }, { required: ["title"] }),
    bodyExample: { title: "Daft Punk – One More Time", by: "Sam" }, res: "SongRequest",
    errors: { 400: "Type a song, for example: Daft Punk – One More Time", 403: "Song requests are turned off", 429: "Lots of requests right now. Try again in a minute." },
    description: "Asks for a song. The same song again adds a vote instead (`merged: true`). At most 30 a minute." },
  "POST /api/requests/{id}/vote": { tag: "Requests", summary: "Vote for a request", params: { id: "A request id (`r…`)." }, res: "SongRequest", errors: { 404: "That request is gone" }, description: "Adds a vote." },
  "PATCH /api/requests/{id}": { tag: "Requests", summary: "Mark a request played", params: { id: "A request id (`r…`)." }, body: obj({ done: bool() }), bodyExample: { done: true }, res: "SongRequest", errors: { 404: "No such request" },
    description: "`{done: true}` when it has been played." },
  "DELETE /api/requests/{id}": { tag: "Requests", summary: "Remove a request", params: { id: "A request id (`r…`)." }, res: OK, errors: { 404: "No such request" }, description: "Removes one request." },
  "DELETE /api/requests": { tag: "Requests", summary: "Remove all requests", res: OK, description: "Removes every request." },

  // ============================================================ Settings
  "PATCH /api/settings": { tag: "Settings", summary: "Change settings", body: "SettingsPatch", res: "Settings", errors: { 400: "Performance is auto, full or lite" },
    description: "Takes any part of the settings and answers them all: brightness, frame rate, light timing, low-power mode, ambient effect, sound capture, metronome, OSC, guest areas, location, night mode, text, MQTT (Home Assistant), Pro DJ Link, Ableton Link and DMX. The MQTT password is never sent back." },

  // ============================================================ Backup & updates
  "GET /api/backup": { tag: "Backup & updates", summary: "Download a backup", res: "Backup",
    description: "Everything except the PIN, as one JSON file. It includes saved passwords and tokens: keep it private." },
  "POST /api/restore": { tag: "Backup & updates", summary: "Restore a backup", body: { anyOf: [R("Backup"), loose("A backup's `data`.")] }, res: OK, errors: { 400: "That doesn't look like a Tempolight backup" },
    bodyExample: { tempolight: "0.4.0", savedAt: "2026-11-04T12:00:00.000Z", data: { devices: [], room: { name: "My room", shapes: [], zones: [] }, scenes: [] } },
    description: "Replaces everything with a backup file (or its `data`). The current PIN is kept." },
  "POST /api/reset": { tag: "Backup & updates", summary: "Reset to defaults", res: OK, description: "Back to the defaults: devices, room, scenes, schedules and settings." },
  "GET /api/update": { tag: "Backup & updates", summary: "Check for an update", res: "Update",
    description: "How this copy was installed, how far behind it is and whether it can update itself (fetches from GitHub for git installs)." },
  "POST /api/update": { tag: "Backup & updates", summary: "Update and restart", res: loose("What was done."), errors: { 400: "Nothing to update in the online demo", 409: null },
    description: "Pulls the new version and restarts Tempolight (installs made with git or the installer). 409 when it can't now." },
  "POST /api/quit": { tag: "Backup & updates", summary: "Quit Tempolight", res: OK, errors: { 400: "Stop Tempolight where it runs (its terminal, service or container)" },
    description: "Stops Tempolight. Only the one-file app can (`canQuit` in the state)." },

  // ============================================================ Wi-Fi
  "GET /api/wifi": { tag: "Wi-Fi", summary: "Get Wi-Fi setup", res: "Wifi", description: "`{available: false}` except on the Raspberry Pi image, where it says what the Wi-Fi setup service is doing." },
  "POST /api/wifi/setup": { tag: "Wi-Fi", summary: "Open the setup hotspot", res: loose("What the service did."), errors: { 400: "Wi-Fi setup is only on the Tempolight Raspberry Pi image", 502: null },
    description: "Leaves the current Wi-Fi and opens the Tempolight-Setup hotspot." },

  // ============================================================ Lock
  "POST /api/lock": { tag: "Lock", summary: "Set a PIN", body: obj({ pin: str("4 to 8 digits.", { pattern: "^\\d{4,8}$" }) }, { required: ["pin"] }), bodyExample: { pin: "1234" },
    res: obj({ locked: bool(), token: str() }), example: { locked: true, token: "5f2d8a9c1e7b4f60" }, errors: { 400: "The PIN must be 4 to 8 digits" },
    description: "Locks settings with a PIN and answers a token so you stay unlocked. Every other token is logged out." },
  "POST /api/unlock": { tag: "Lock", summary: "Unlock", body: obj({ pin: str() }, { required: ["pin"] }), bodyExample: { pin: "1234" }, res: obj({ token: str() }), example: { token: "5f2d8a9c1e7b4f60" }, errors: { 403: "Wrong PIN" },
    description: "Answers a token valid for 12 hours: send it as the `x-tempolight-token` header (or `?token=`). Each try takes 300 ms. Tokens are kept in memory, so a restart logs everyone out." },
  "DELETE /api/lock": { tag: "Lock", summary: "Remove the PIN", res: obj({ locked: bool() }), example: { locked: false }, description: "Removes the PIN lock." },

  // ============================================================ Apple Home
  "GET /api/homekit": { tag: "Apple Home", summary: "Get the HomeKit bridge", res: "HomeKit", description: "Whether the bridge is on, its setup code and QR code address, and the paired controllers." },
  "PATCH /api/homekit": { tag: "Apple Home", summary: "Turn the bridge on or off", body: obj({ enabled: bool() }), bodyExample: { enabled: true }, res: "HomeKit", description: "Turns the HomeKit bridge on or off." },
  "POST /api/homekit/reset": { tag: "Apple Home", summary: "Reset pairing", res: "HomeKit", description: "Forgets every paired controller and makes a new identity and setup code. Then remove the old Tempolight from the Home app." },
  "DELETE /api/homekit/pairings/{id}": { tag: "Apple Home", summary: "Forget a controller", params: { id: "A pairing id from `pairings`." }, res: "HomeKit", errors: { 404: "No such controller" }, description: "Forgets one paired controller." },

  // ============================================================ Integrations
  "GET /api/integrations": { tag: "Integrations", summary: "Get integrations", res: "Integrations", description: "The settings and live status of OBS, the games, Twitch, Discord and the Stream Deck plugin. Passwords, the Twitch sign-in and the Discord webhook are never sent back." },
  "PATCH /api/integrations/obs": { tag: "Integrations", summary: "Change OBS", res: loose("The OBS settings and status."), errors: { 400: "OBS's address looks like ws://127.0.0.1:4455" },
    body: obj({ enabled: bool(), url: str(), password: str(), clearPassword: bool(), sceneMap: arr(obj({ obs: str("An OBS scene."), scene: str("A Tempolight scene id.") })), onStreamStart: str(), onStreamStop: str(), onRecordStart: str(),
      tally: obj({ enabled: bool(), when: en(["recording", "streaming", "either"]), target: str(), color: str() }) }), bodyExample: { enabled: true, url: "ws://127.0.0.1:4455", sceneMap: [{ obs: "Just chatting", scene: "chill" }] },
    description: "Connects to OBS (WebSocket v5): Tempolight scenes for OBS scenes, scenes when streaming or recording starts, and a tally light." },
  "PATCH /api/integrations/twitch": { tag: "Integrations", summary: "Change Twitch", res: loose("The Twitch settings and status."), errors: { 400: "A Twitch channel name is 3 to 25 letters, digits or _" },
    body: obj({ chat: loose("`{enabled, channel, prefix, who, cooldownSec, userCooldownSec, commands, scenes, effects}`."), clientId: str(), eventsOn: bool(), target: str(), events: loose("A reaction per event: follow, subscribe, resub, gift, raid, cheer.") }),
    bodyExample: { chat: { enabled: true, channel: "mychannel", prefix: "!" } }, description: "Chat commands (scene, effect, flash, colour, strobe, drop) and reactions to follows, subs, raids and cheers." },
  "POST /api/integrations/twitch/login": { tag: "Integrations", summary: "Sign in to Twitch", body: obj({ clientId: str() }), bodyOptional: true, bodyExample: { clientId: "abcdefghijklmnopqrstuvwxyz0123" },
    res: obj({ userCode: str(), uri: str(), expiresAt: num() }), example: { userCode: "ABCD-EFGH", uri: "https://www.twitch.tv/activate", expiresAt: 1762201800000 }, errors: { 400: "Paste your Twitch application's Client ID first" },
    description: "Starts the device-code sign-in: enter `userCode` at `uri` (twitch.tv/activate)." },
  "DELETE /api/integrations/twitch/login": { tag: "Integrations", summary: "Sign out of Twitch", res: loose("The Twitch settings and status."), description: "Forgets the Twitch sign-in." },
  "POST /api/integrations/twitch/test": { tag: "Integrations", summary: "Test a Twitch reaction", body: obj({ kind: en(["follow", "subscribe", "resub", "gift", "raid", "cheer"]) }, { required: ["kind"] }), bodyExample: { kind: "raid" }, res: OK,
    errors: { 400: "kind is follow, subscribe, resub, gift, raid or cheer" }, description: "Runs that event's reaction, as if it happened." },
  "PATCH /api/integrations/discord": { tag: "Integrations", summary: "Change Discord", res: loose("The Discord settings and status."), errors: { 400: "Paste the webhook address Discord shows (https://discord.com/api/webhooks/…)" },
    body: obj({ webhook: str("`\"\"` removes it."), username: str(), nowPlaying: bool(), scenes: bool(), twitch: bool() }), bodyExample: { webhook: "https://discord.com/api/webhooks/123/abc", nowPlaying: true },
    description: "A Discord webhook that posts what plays, scene changes and Twitch events." },
  "PATCH /api/integrations/docs": { tag: "Integrations", summary: "Let the docs site try API calls", body: obj({ tryIt: bool("Allow the docs site's Try it panel.") }), bodyExample: { tryIt: true },
    res: obj({ tryIt: bool(), origins: arr(str(), "The docs site's addresses that may call the API.") }), example: { tryIt: true, origins: ["https://tempolight.pages.dev", "http://localhost:3000", "http://127.0.0.1:3000"] },
    errors: { 400: "tryIt is true or false" },
    description: "Off by default: browsers may not call the API from other websites. On, the docs site (https://tempolight.pages.dev/docs) may send requests here from its API reference, with CORS for that address only; the PIN lock still applies." },
  "POST /api/integrations/discord/test": { tag: "Integrations", summary: "Test Discord", res: OK, errors: { 400: "Paste a Discord webhook address first", 502: "Discord doesn't know this webhook" }, description: "Posts a test message." },
  "GET /api/integrations/streamdeck/plugin": { tag: "Integrations", summary: "Download the Stream Deck plugin", content: { "application/octet-stream": { schema: str(undefined, { format: "binary" }) } },
    extraResponses: { 302: { description: "No plugin in this copy: a redirect to the releases page." } }, description: "The `.streamDeckPlugin` file, not JSON (or a redirect to the releases page)." },

  // ============================================================ Games
  "PATCH /api/integrations/games/{game}": { tag: "Games", summary: "Change a game", params: { game: "`cs2` or `dota2`." }, res: "Game", errors: { 400: "mode is blend or takeover", 404: 'Unknown game "x" (cs2 or dota2)' },
    body: obj({ enabled: bool("Turning it on makes its token."), intensity: num(undefined, { minimum: 0, maximum: 1 }), mode: en(["blend", "takeover"]), healthTarget: str(), effectsTarget: str(), manaTarget: str(), ambientTarget: str(),
      kills: bool(), flashbang: bool(), bomb: bool(), rounds: bool(), roshan: bool(), daynight: bool() }), bodyExample: { enabled: true, intensity: 0.8, mode: "blend" },
    description: "Lights that react to the game: health, flashbangs, the bomb, kills, rounds (CS2), mana, Roshan, day and night (Dota 2). Targets are `all`, `off`, `zone:<id>` or `dev:<id>`." },
  "POST /api/integrations/games/{game}/token": { tag: "Games", summary: "Make a new game token", params: { game: "`cs2` or `dota2`." }, res: obj({ token: str() }), example: { token: "9f8e7d6c5b4a39281706f5e4d3c2b1a0" },
    errors: { 404: "Unknown game" }, description: "A new token: the installed config file stops working until it is downloaded again." },
  "GET /api/integrations/games/{game}/cfg": { tag: "Games", summary: "Get the game's config file", params: { game: "`cs2` or `dota2`." },
    query: [{ name: "url", required: true, description: "Tempolight's address as the game's computer reaches it.", schema: str(undefined, { example: "http://127.0.0.1:8080" }) }],
    res: obj({ filename: str(), folder: str(), content: str() }), example: { filename: "gamestate_integration_tempolight.cfg", folder: "game/csgo/cfg", content: "\"Tempolight\"\n{\n …\n}\n" },
    errors: { 400: "url is Tempolight's address as the game's computer reaches it, like http://127.0.0.1:8080", 404: "Unknown game" },
    description: "The game's `gamestate_integration_tempolight.cfg`, with its token, and the folder it goes in." },
  "POST /api/integrations/games/{game}/test": { tag: "Games", summary: "Test a game event", params: { game: "`cs2` or `dota2`." },
    body: obj({ what: en(["flash", "bomb", "kill", "win", "lose", "roshan", "night", "day", "low"]) }, { required: ["what"] }), bodyExample: { what: "bomb" }, res: OK,
    errors: { 400: "Turn Counter-Strike 2 on first", 404: "Unknown game" }, description: "Pretends it happened." },
  "POST /api/gsi/{game}": { tag: "Games", summary: "Game state (from the game)", params: { game: "`cs2` or `dota2`." },
    body: loose("Valve game-state integration JSON, with `auth.token`."), bodyExample: { provider: { name: "Counter-Strike 2" }, player: { state: { health: 100, flashed: 0 } }, auth: { token: "9f8e7d6c5b4a39281706f5e4d3c2b1a0" } },
    res: obj({ ok: bool(), off: bool("The game is turned off in Tempolight.") }), example: { ok: true },
    errors: { 403: "Wrong or missing game token: download the config file again from Tempolight's Integrations page", 404: "Unknown game (cs2 or dota2)", 429: "Too many updates" },
    description: "Where the games post their state. Open, but only with the token from the game's config file (`auth.token`). At most 40 a second; 30 wrong tokens in a minute block it for a minute." },
};
